--
-- Table structure for table `fraud_audit_log`
--

DROP TABLE IF EXISTS `fraud_audit_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fraud_audit_log` (
  `audit_id` varchar(128) NOT NULL,
  `actor_type` varchar(32) NOT NULL DEFAULT 'SYSTEM',
  `actor_id` varchar(128) NOT NULL,
  `customer_id` varchar(64) DEFAULT NULL,
  `incident_id` varchar(128) DEFAULT NULL,
  `event_type` varchar(128) NOT NULL,
  `event` varchar(128) NOT NULL,
  `reason` text,
  `evidence` json DEFAULT NULL,
  `decision` varchar(128) DEFAULT NULL,
  `confidence` decimal(5,4) DEFAULT NULL,
  `action` varchar(128) DEFAULT NULL,
  `approval` varchar(128) DEFAULT NULL,
  `result` varchar(128) DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`audit_id`),
  KEY `idx_audit_actor_type` (`actor_type`),
  KEY `idx_audit_actor_id` (`actor_id`),
  KEY `idx_audit_cust` (`customer_id`),
  KEY `idx_audit_inc` (`incident_id`),
  KEY `idx_audit_evt_type` (`event_type`),
  KEY `idx_audit_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

