DROP TABLE IF EXISTS `fraud_incidents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fraud_incidents` (
  `incident_id` varchar(128) NOT NULL,
  `customer_id` varchar(128) NOT NULL,
  `fraud_type` varchar(128) NOT NULL,
  `severity` varchar(64) NOT NULL,
  `reason` text,
  `risk_score` int DEFAULT '0',
  `risk_level` varchar(64) NOT NULL,
  `action` varchar(128) NOT NULL,
  `requires_customer_action` tinyint(1) DEFAULT '0',
  `requires_admin_review` tinyint(1) DEFAULT '0',
  `restriction_minutes` int DEFAULT NULL,
  `ai_attack_pattern` text,
  `ai_finding` text,
  `ai_confidence` decimal(5,4) DEFAULT NULL,
  `ai_recommendation` text,
  `source_event_id` varchar(128) DEFAULT NULL,
  `source_event_type` varchar(128) DEFAULT NULL,
  `ip_address` varchar(128) DEFAULT NULL,
  `device_id` varchar(128) DEFAULT NULL,
  `session_id` varchar(128) DEFAULT NULL,
  `timestamp` varchar(128) NOT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`incident_id`),
  KEY `idx_fraud_inc_cust` (`customer_id`),
  KEY `idx_fraud_inc_risk` (`risk_level`),
  KEY `idx_fraud_inc_type` (`fraud_type`),
  KEY `idx_fraud_inc_sev` (`severity`),
  KEY `idx_fraud_inc_created` (`created_at`),
  KEY `idx_fraud_inc_action` (`action`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
