CREATE TABLE `fraud_otp_challenges` (
  `id` int NOT NULL AUTO_INCREMENT,
  `challenge_id` varchar(128) NOT NULL,
  `customer_id` varchar(128) NOT NULL,
  `incident_id` varchar(128) DEFAULT NULL,
  `phone_reference` varchar(128) DEFAULT NULL,
  `otp_hash` varchar(255) NOT NULL,
  `purpose` varchar(64) NOT NULL DEFAULT 'STEP_UP_VERIFICATION',
  `status` varchar(32) NOT NULL DEFAULT 'PENDING',
  `attempt_count` int NOT NULL DEFAULT '0',
  `max_attempts` int NOT NULL DEFAULT '5',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `expires_at` datetime NOT NULL,
  `verified_at` datetime DEFAULT NULL,
  `is_demo` tinyint(1) NOT NULL DEFAULT '0',
  `metadata` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `challenge_id` (`challenge_id`),
  KEY `idx_otp_chall_id` (`challenge_id`),
  KEY `idx_otp_chall_cust` (`customer_id`),
  KEY `idx_otp_chall_inc` (`incident_id`),
  KEY `idx_otp_chall_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
