--
-- Table structure for table `fraud_restrictions`
--

DROP TABLE IF EXISTS `fraud_restrictions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fraud_restrictions` (
  `restriction_id` varchar(128) NOT NULL,
  `customer_id` varchar(64) NOT NULL,
  `incident_id` varchar(128) DEFAULT NULL,
  `restriction_type` varchar(64) NOT NULL DEFAULT 'TEMPORARY_RESTRICTION',
  `status` varchar(32) NOT NULL DEFAULT 'ACTIVE',
  `reason` text,
  `started_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `expires_at` datetime DEFAULT NULL,
  `released_at` datetime DEFAULT NULL,
  `released_by` varchar(128) DEFAULT NULL,
  `release_reason` text,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`restriction_id`),
  KEY `idx_fraud_restr_cust` (`customer_id`),
  KEY `idx_fraud_restr_status` (`status`),
  KEY `idx_fraud_restr_expires` (`expires_at`),
  KEY `idx_fraud_restr_inc` (`incident_id`),
  CONSTRAINT `fraud_restrictions_ibfk_2` FOREIGN KEY (`incident_id`) REFERENCES `fraud_incidents` (`incident_id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

